#if UNITY_EDITOR
using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
using HeartOfTheRain.App.Profile;
namespace HeartOfTheRain.Verification {
    public static class BackendHttpVerification {
        [Serializable] sealed class Credential {public string playerId,token;}
        [Serializable] sealed class Bootstrap {public string origin,runId;public Credential primary,recovery;}
        [Serializable] sealed class Report {public string status,utc,unity,scope="Native Unity Editor coroutine execution with actual HTTP to a separate loopback FastAPI process and isolated durable profiles. No mock transport, ordinary profile migration, APK, Android or UI certification.";public int checks;public List<string> passed=new List<string>(),failures=new List<string>();}
        sealed class FaultRepository:IProfileRepository {
            public FileProfileRepository inner;public bool before,afterCredit;
            public PlayerProfile Read()=>inner.Read();
            public PlayerProfile Commit(long revision,PlayerProfile next){if(before){before=false;throw new IOException("Injected local save failure");}var saved=inner.Commit(revision,next);if(afterCredit&&saved.giftClaims>0){afterCredit=false;throw new IOException("Injected lost local credit confirmation");}return saved;}
        }
        static Report report;static Bootstrap config;static string root;static double started;
        static Stack<IEnumerator> stack;static AsyncOperation waiting;
        static void Check(bool ok,string name){report.checks++;if(!ok)throw new InvalidOperationException(name);report.passed.Add(name);}
        static void Reject(Action action,string name){try{action();}catch(ArgumentException){Check(true,name);return;}throw new Exception(name);}
        public static void Run(){
            report=new Report{utc=DateTime.UtcNow.ToString("o"),unity=Application.unityVersion};
            try{string path=Environment.GetEnvironmentVariable("HOTR_BACKEND_VERIFICATION_CONFIG");if(string.IsNullOrEmpty(path))throw new InvalidOperationException("Explicit backend verification configuration required");string allowed=Path.GetFullPath("../.verification-cache/Backend/");if(!Path.GetFullPath(path).StartsWith(allowed,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Backend fixture must be inside ignored verification cache");config=JsonUtility.FromJson<Bootstrap>(File.ReadAllText(path));Guid id;if(config==null||!Guid.TryParseExact(config.runId,"N",out id))throw new InvalidOperationException("Invalid fixture identity");root=Path.GetFullPath("../.verification-cache/Backend/Unity-"+config.runId);Directory.CreateDirectory(root);started=EditorApplication.timeSinceStartup;stack=new Stack<IEnumerator>();stack.Push(Checks());EditorApplication.update+=Tick;}
            catch(Exception){report.failures.Add("Backend fixture configuration unavailable");Finish();}
        }
        static void Tick(){
            try{if(EditorApplication.timeSinceStartup-started>180)throw new TimeoutException("Native HTTP fixture timed out");if(waiting!=null&&!waiting.isDone)return;waiting=null;
                if(stack.Count==0){Finish();return;}var routine=stack.Peek();if(!routine.MoveNext()){stack.Pop();return;}if(routine.Current is IEnumerator nested)stack.Push(nested);else if(routine.Current is AsyncOperation operation)waiting=operation;
            }catch(Exception e){report.failures.Add(e.GetType().Name+": "+e.Message);Finish();}
        }
        static BackendClient Client(Credential credential)=>new BackendClient(config.origin,credential.token,true);
        static FileProfileRepository Repository(string name,string player)=>new FileProfileRepository(Path.Combine(root,name),()=>{var p=PlayerProfile.New(new[]{5,5,3,2});p.playerId=player;return p;});
        static PendingGift Pending(GiftOffer offer)=>new PendingGift{requestId=Guid.NewGuid().ToString("N"),offerId=offer.id,day=offer.day,step=offer.step,schedule=offer.schedule,expectedGrant=offer.grant.Copy()};
        static IEnumerator Checks(){
            Reject(()=>new BackendClient("http://example.com/",config.primary.token,true),"Cleartext non-loopback endpoint rejected");Reject(()=>new BackendClient(config.origin,config.primary.token),"Local HTTP requires explicit development opt-in");Reject(()=>new BackendClient("https://user:password@example.com/",config.primary.token),"Credentials cannot be embedded in origin");Reject(()=>new BackendClient("https://example.com/?secret=value",config.primary.token),"Origin query rejected");Reject(()=>new BackendClient("https://example.com/","bad\r\nheader"),"Invalid bearer credential rejected");
            var client=Client(config.primary);BackendResult<BackendTime> time=null;yield return client.Time(value=>time=value);Check(time!=null&&time.ok&&time.value.serverUtc>0&&time.value.day==time.value.serverUtc/86400,"Actual authenticated server UTC received");
            var faults=new FaultRepository{inner=Repository("primary",config.primary.playerId)};var service=new ProfileService(faults);var session=new BackendGiftSession(service,client,GiftSchedule.Preview());bool refreshed=false;string error=null;yield return session.Refresh((ok,why)=>{refreshed=ok;error=why;});Check(refreshed&&error==null&&session.Offer.step==0,"HTTP offer matches the approved initial schedule");
            faults.before=true;RewardGrant grant=null;yield return session.Claim((value,why)=>{grant=value;error=why;});Check(grant==null&&error=="local_claim_unavailable"&&service.Read().coins==1250&&service.Read().pendingGift==null,"Failed local intent save prevents remote reward credit");
            BackendResult<BackendAccount> account=null;yield return client.Account(value=>account=value);Check(account.ok&&account.value.rewardTotals[0]==0,"Server reward ledger unchanged after rejected local intent");
            faults.afterCredit=true;yield return session.Claim((value,why)=>{grant=value;error=why;});Check(error=="claim_confirmation_unavailable"&&service.Read().coins==1300&&service.Read().giftClaims==1,"Lost local credit confirmation leaves exactly one saved grant");
            service=new ProfileService(Repository("primary",config.primary.playerId));session=new BackendGiftSession(service,client,GiftSchedule.Preview());yield return session.Claim((value,why)=>{grant=value;error=why;});Check(error==null&&grant==null&&service.Read().coins==1300,"Recreated client/session does not credit an already confirmed day twice");
            yield return client.Account(value=>account=value);Check(account.ok&&account.value.rewardTotals[0]==50&&account.value.completed==0&&account.value.balanceScope=="reward_credits_only","Server confirms one credit without inventing campaign progress or full-wallet sync");
            BackendResult<BackendReceipts> receipts=null;yield return client.Receipts(0,value=>receipts=value);Check(receipts.ok&&receipts.value.receipts.Length==1&&receipts.value.receipts[0].grant.coins==50,"Durable receipt recovery endpoint returns the one server credit");
            string attempt=Guid.NewGuid().ToString("N");service.Reserve(attempt,1,"native-http-fixture",new int[4],50,1);service.CommitStart(attempt);service.Win(attempt);var events=new ProfileEventFeed(service).Capture().events.ToArray();BackendResult<BackendEventAck> ack=null;yield return client.Events(events,value=>ack=value);Check(ack.ok&&ack.value.accepted==events.Length&&!ack.value.rewarded&&ack.value.trust=="client_reported","Actual Unity audit payload accepted strictly as client-reported data");yield return client.Events(events,value=>ack=value);Check(ack.ok&&ack.value.accepted==0&&ack.value.duplicates==events.Length,"Actual HTTP resend deduplicates every stable event ID");yield return client.Account(value=>account=value);Check(account.value.completed==0&&account.value.rewardTotals[0]==50,"Reported client win cannot grant currency or unlock server progression");
            var recoveryClient=Client(config.recovery);var recoveryService=new ProfileService(Repository("recovery",config.recovery.playerId));var recoverySession=new BackendGiftSession(recoveryService,recoveryClient,GiftSchedule.Preview());yield return recoverySession.Refresh((ok,why)=>{refreshed=ok;error=why;});Check(refreshed,"Second isolated account receives its own offer");var pending=Pending(recoverySession.Offer);recoveryService.Change(p=>{p.pendingGift=pending;return true;});BackendResult<BackendDecision> decision=null;yield return recoveryClient.Claim(pending,value=>decision=value);Check(decision.ok&&recoveryService.Read().coins==1250&&recoveryService.Read().pendingGift!=null,"Simulated lost HTTP confirmation leaves durable local intent and a server receipt");
            var badClient=new BackendClient(config.origin,new string('x',43),true);var denied=new BackendGiftSession(recoveryService,badClient,GiftSchedule.Preview());yield return denied.Claim((value,why)=>{grant=value;error=why;});Check(error=="http_401"&&recoveryService.Read().coins==1250&&recoveryService.Read().pendingGift!=null,"Authentication failure preserves pending claim without credit");
            recoveryService=new ProfileService(Repository("recovery",config.recovery.playerId));recoverySession=new BackendGiftSession(recoveryService,recoveryClient,GiftSchedule.Preview());yield return recoverySession.Claim((value,why)=>{grant=value;error=why;});Check(error==null&&grant!=null&&grant.coins==50&&recoveryService.Read().coins==1300&&recoveryService.Read().pendingGift==null,"Recreated session reconciles the original server receipt once");yield return recoverySession.Claim((value,why)=>{grant=value;error=why;});Check(error==null&&grant==null&&recoveryService.Read().coins==1300,"Repeated recovered claim remains final");
            yield return recoveryClient.Events(events,value=>ack=value);Check(!ack.ok&&ack.status==403,"Another authenticated account cannot ingest this profile's stream");
            var mismatch=new ProfileService(Repository("mismatch",Guid.NewGuid().ToString("N")));var wrongSession=new BackendGiftSession(mismatch,client,GiftSchedule.Preview());yield return wrongSession.Claim((value,why)=>{grant=value;error=why;});Check(error=="account_mismatch"&&mismatch.Read().pendingGift==null&&mismatch.Read().coins==1250,"Account/profile mismatch rejected before remote claim or local intent");
            Check(service.Read().coins==1350&&recoveryService.Read().coins==1300,"Only the staged first clear and two isolated gift credits changed test balances");
        }
        static void Finish(){EditorApplication.update-=Tick;waiting=null;if(stack!=null){while(stack.Count>0){var disposable=stack.Pop() as IDisposable;disposable?.Dispose();}}report.status=report.failures.Count==0?"PASS_NATIVE_BACKEND_HTTP":"FAIL_NATIVE_BACKEND_HTTP";string directory=Path.GetFullPath("../Verification/Evidence/Backend");Directory.CreateDirectory(directory);File.WriteAllText(Path.Combine(directory,"Native_HTTP_Checks.json"),JsonUtility.ToJson(report,true));config=null;EditorApplication.Exit(report.failures.Count==0?0:1);}
    }
}
#endif
